  Future<List<Book>> fetchBooks() async {
    await Future.delayed(Duration(seconds: 2));
    return _books;
  }

  List<Book> getBooks() => _books;

  Book? getBookById(String id) {
    return _books.firstWhere(
      (book) => book.id == id,
      orElse:
          () => Book(
            id: '',
            title: 'Not Found',
            category: 'Unknown',
            coverUrl: '',
            price: 0,
            pages: 0,
          ),
    );
  }
